const homeStatus = msg.home_status || "unknown";

const now = new Date();

// In many Wait Until node configurations, timeout information is added to msg.
// If your node uses a different field, adjust this after checking the debug output.
const motionConfirmed = msg.motion_confirmed === true;

let action = "notify";
let priority = "normal";
let securityState = "watching";
let reason = "A door was opened";

if (homeStatus === "exempt") {
    action = "ignore";
    priority = "none";
    securityState = "exempt";
    reason = "Door opened, but security logic is exempt";
}

else if (homeStatus === "party") {
    action = "notify";
    priority = "low";
    securityState = "watching";
    reason = "Door opened during party mode";
}

else if (homeStatus === "away") {
    if (motionConfirmed) {
        action = "alert";
        priority = "critical";
        securityState = "alarm";
        reason = "Door opened while away, followed by indoor motion";
    } else {
        action = "alert";
        priority = "high";
        securityState = "warning";
        reason = "Door opened while away, but no indoor motion was detected";
    }
}

else if (homeStatus === "night") {
    if (motionConfirmed) {
        action = "alert";
        priority = "high";
        securityState = "warning";
        reason = "Door opened at night, followed by indoor motion";
    } else {
        action = "notify";
        priority = "normal";
        securityState = "watching";
        reason = "Door opened at night, but no indoor motion was detected";
    }
}

else {
    if (motionConfirmed) {
        action = "notify";
        priority = "normal";
        securityState = "watching";
        reason = "Door opened, followed by indoor motion";
    } else {
        action = "notify";
        priority = "normal";
        securityState = "watching";
        reason = "Door opened, but no indoor motion was detected";
    }
}

msg.security_decision = {
    home_status: homeStatus,
    motion_confirmed: motionConfirmed,
    action: action,
    priority: priority,
    security_state: securityState,
    reason: reason,
    detected_at: now.toISOString()
};

return msg;
